    def backtrack(nums, result=None):
        """Try to find a sequence of operations to reduce nums to 1."""
        if result is not None:
            return result

        if len(nums) == 1:
            if nums[0] == 1:
                return result
            return None

        n_nums = len(nums)
        # Try all pairs of indices
        for i in range(n_nums):
            for j in range(i+1, n_nums):
                x, y = nums[i], nums[j]
                new_val = f(x + y)

                # Create new list without indices i and j
                new_nums = []
                for idx in range(n_nums):
                    if idx != i and idx != j:
                        new_nums.append(nums[idx])
                new_nums.append(new_val)

                result = backtrack(new_nums, result)
                if result is not None:
                    return result

        return None

    initial_ops = []
    initial_nums = sorted(a)
    result = backtrack(initial_nums, initial_ops)

    if result is None:
        return "NO"

    # Reconstruct operations from the result path
    # We need to track the path properly in backtrack
    operations = []

    def backtrack_with_path(nums, path=None):
        """Track operations path recursively."""
        if path is None:
            path = []

        if len(nums) == 1:
            if nums[0] == 1:
                return path
            return None

        n_nums = len(nums)
        for i in range(n_nums):
            for j in range(i+1, n_nums):
                x, y = nums[i], nums[j]
                new_val = f(x + y)

                new_nums = [nums[k] for k in range(n_nums) if k != i and k != j]
                new_nums.append(new_val)

                result_path = backtrack_with_path(new_nums, path + [(nums[i], nums[j])])
