import sys
from collections import deque

class Dinic:
    def __init__(self, n):
        self.n = n
        self.graph = [[] for _ in range(n)]
        self.level = []

    def add_edge(self, u, v, capacity):
        self.graph[u].append([v, capacity, len(self.graph[v])])
        self.graph[v].append([u, 0, len(self.graph[u]) - 1])

    def bfs(self, s, t):
        self.level = [-1] * self.n
        self.level[s] = 0
        queue = deque([s])
        while queue:
            u = queue.popleft()
            for v, cap, _ in self.graph[u]:
                if cap > 0 and self.level[v] < 0:
                    self.level[v] = self.level[u] + 1
                    queue.append(v)
        return self.level[t] >= 0

    def dfs(self, u, t, flow, ptr):
        if u == t or flow == 0:
            return flow
        for i in range(ptr[u], len(self.graph[u])):
            ptr[u] = i
            v, cap, rev = self.graph[u][i]
            if self.level[v] == self.level[u] + 1 and cap > 0:
                pushed = self.dfs(v, t, min(flow, cap), ptr)
                if pushed > 0:
                    self.graph[u][i][1] -= pushed
                    self.graph[v][rev][1] += pushed
                    return pushed
        return 0

    def max_flow(self, s, t):
        flow = 0
        while self.bfs(s, t):
            ptr = [0] * self.n
            while True:
                pushed = self.dfs(s, t, float('inf'), ptr)
                if pushed == 0:
                    break
                flow += pushed
        return flow

def solve():
    lines = sys.stdin.read().split()
    idx = 0
    n = int(lines[idx]); idx += 1
    m = int(lines[idx]); idx += 1

    a = [int(lines[idx + i]) for i in range(n)]; idx += n
    b = [int(lines[idx + i]) for i in range(n)]; idx += n

    adj = [[] for _ in range(n)]
    for _ in range(m):
        u = int(lines[idx]); v = int(lines[idx+1]); idx += 2
        adj[u-1].append(v-1)
        adj[v-1].append(u-1)

    if sum(a) != sum(b):
        return "NO"

    source = 0
    sink = 2 * n + 1
    mf = Dinic(2 * n + 2)
    edges = []

    for i in range(n):
        mf.add_edge(source, i + 1, a[i])
        for j in range(n):
            if i == j or (j in adj[i]):
                mf.add_edge(i + 1, j + 1 + n, float('inf'))
        mf.add_edge(sink + 1 - (n + 1) + j*n + i, sink, min(a[i], b[j]))

    total = mf.max_flow(source, sink)
    if total != sum(a):
        return "NO"

    # Build adjacency
    mf2 = Dinic(mf.n)
    for i in range(mf.n):
        for j, cap in enumerate(mf.graph[i]):
            if cap[0] < cap[1]:  # Original was capacity
                mf2.add_edge(i, j, cap[1] - cap[0])

    # Matrix
    result = [[0] * n for _ in range(n)]

    for i in range(n):
        u = i + 1
        for j in range(n):
            caps = 0
            for edge in mf.graph[u]:
                if edge[0] == j + 1 + n:
                    caps = edge[1]
                    break
            result[i][j] = caps

    return "YES\n" + "\n".join(" ".join(map(str, row)) for row in result)

