import random

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    # Parse the adjacency matrix
    # adj[i][j] = cost for city i to build rail to city j
    adj = [[0] * n for _ in range(n)]
    for i in range(n):
        row = list(map(int, lines[1 + i].split()))
        idx = 0
        for j in range(n):
            if j != i:
                adj[i][j] = row[idx]
                idx += 1

    # Precompute rank preferences: lower rank = better preference
    # rank[i][j] = rank of city j in city i's preferences
    rank = [[0] * n for _ in range(n)]
    for i in range(n):
        # Sort all cities by cost (lower cost = better = lower rank value)
        items = [(adj[i][j], j) for j in range(n) if j != i]
        items.sort()
        for r, (cost, city) in enumerate(items, 1):  # Start from 1
            rank[i][city] = r

    # Check if a matching is stable
    def is_stable(matching):
        """Return True if matching is stable, False otherwise"""
        for i in range(n):
            if matching[i] == -1:
                return False
            for j in range(i + 1, n):
                # Check if i and j are NOT paired with each other
                if matching[i] != j and matching[j] != i:
                    # Check if both prefer each other over their current partners
                    # rank[i][j] < rank[i][matching[i]] means i prefers j
                    # rank[j][i] < rank[j][matching[j]] means j prefers i
                    if rank[i][j] < rank[i][matching[i]] and rank[j][i] < rank[j][matching[j]]:
                        return False
        return True

    def find_blocking_pair(matching):
        """Find a blocking pair (i, j) if one exists"""
        for i in range(n):
            for j in range(i + 1, n):
                if matching[i] != j and matching[j] != i:
                    if rank[i][j] < rank[i][matching[i]] and rank[j][i] < rank[j][matching[j]]:
                        return (i, j)
        return None

    # Try multiple initial matchings to find a stable one
    best_matching = None

    def make_random_matching():
        """Create a random perfect matching"""
        matching = list(range(n))
        random.shuffle(matching)
        result = [-1] * n
        for i in range(0, n, 2):
            if i + 1 < n:
                u, v = matching[i], matching[i + 1]
                result[u] = v
                result[v] = u
        return result

    # Try 200 random initial matchings
    for _ in range(200):
        matching = make_random_matching()

        # Try to improve by resolving blocking pairs
        for _ in range(100):
            blocking = find_blocking_pair(matching)
            if blocking is None:
                break
            i, j = blocking
            matching[i] = j
            matching[j] = i

        if is_stable(matching):
            best_matching = matching
            break

    if best_matching is None:
        # Also try deterministic approaches
        # Always pair i with (i+1) % n (bi-partition into pairs)
        matching = [-1] * n
        for i in range(0, n, 2):
            if i + 1 < n:
                u, v = i, i + 1
                matching[u] = v
                matching[v] = u

        # Try swapping adjacent pairs
        improved = False
        for _ in range(50):
            swapped = False
            for i in range(0, n - 1, 2):
                for j in range(i + 1, n - 1, 2):
