                        orig_matchings = list(matching)
                        u1, v1 = i, i + 1
                        u2, v2 = j, j + 1

                        # Try creating new pairings (i,j) and (k,l) where original were (i,k) and (j,l)
                        if matching[u1] == v2 and matching[u2] == v1:
                            matching[u1] = v2
                            matching[u2] = v1
                            if is_stable(matching):
