    # pattern 2: (r + 2*c) % 4 + 1
    # pattern 3: (r + 3*c) % 4 + 1
    # pattern 4: (2*r + c) % 4 + 1
    # pattern 5: (2*r + 3*c) % 4 + 1
    # pattern 6: (3*r + 2*c) % 4 + 1
    # pattern 7: (3*r + c) % 4 + 1

