        lambda r, c: (r + c) % 4,
        lambda r, c: (r + 2*c) % 4,
        lambda r, c: (2*r + c) % 4,
        lambda r, c: (2*r + 3*c) % 4,
        lambda r, c: (3*r + c) % 4,
        lambda r, c: (3*r + 2*c) % 4,
