        parts = list(map(int, lines[idx].split()))
        idx += 1
        k = parts[0]
        clauses.append(parts[1:])

    if not clauses:
        return "YES\n" + "0" * m

    # For each variable, track which clauses it appears in
    var_occurrences = [[] for _ in range(m + 1)]
    for clause_idx, clause in enumerate(clauses):
        for lit in clause:
