def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    arr = list(map(int, lines[1].split()))

    MOD = 1000000007

    # Identify used values and empty positions
    used_values = set()
    empty_positions = []

    for i in range(n):
        if arr[i] == -1:
            empty_positions.append(i + 1)  # 1-indexed position
        else:
            used_values.add(arr[i])

    k = len(empty_positions)
    m_count = 0

    # Count m: number of empty positions where the position index is available
    # (i.e., the value equals the position index and this value isn't already used)
    for pos in empty_positions:
        if pos not in used_values:
            m_count += 1

    # Precompute factorials up to k
    fact = [1] * (k + 1)
    for i in range(1, k + 1):
        fact[i] = (fact[i-1] * i) % MOD

    # Precompute modular inverse of factorials efficiently
    inv_fact = [1] * (k + 1)

    def power(a, b, m):
        res = 1
        a %= m
        while b > 0:
            if b % 2 == 1:
                res = (res * a) % m
            a = (a * a) % m
            b //= 2
        return res

    def modInverse(n, m):
        return power(n, m - 2, m)

    inv_fact[k] = modInverse(fact[k], MOD)
    for i in range(k - 1, -1, -1):
        inv_fact[i] = (inv_fact[i+1] * (i + 1)) % MOD

    ans = 0

    # Use inclusion-exclusion principle to count derangements
    for i in range(m_count + 1):
        if m_count >= i:
            # C(m_count, i) * (k - i)! * (-1)^i
            comb = fact[m_count] * inv_fact[i] % MOD
            comb = comb * inv_fact[m_count - i] % MOD
            term = comb * fact[k - i] % MOD

            if i % 2 == 1:
                ans = (ans - term + MOD) % MOD
            else:
                ans = (ans + term) % MOD

    return str(ans) + '\n'
