    for i in range(1, N + 1):
        row = list(map(int, lines[line_idx].split()))
        # Row i has N-1 values for connecting to other cities
        pos = 0
        for j in range(1, N + 1):
            if i != j:
                cost[i][j] = row[pos]
                pos += 1
        line_idx += 1

    # match[i] = partner of city i (0 if not matched)
    match = [0] * (N + 1)

    def is_stable():
        # Check if any two cities would both prefer each other over their current partners
        for i in range(1, N + 1):
            if match[i] == 0:
                continue  # unpaired city

            for j in range(1, N + 1):
                if i == j or match[j] == 0:
                    continue

                if j == match[i] or i == match[j]:
                    continue  # already paired to each other

                # i is paired with match[i], j is paired with match[j]
                # Do both prefer each other?
                if cost[i][j] < cost[i][match[i]] and cost[j][i] < cost[j][match[j]]:
                    return False
        return True

    def backtrack(start_city, used):
        # Find an unused city to pair
        city = -1
        for c in range(start_city, N + 1):
            if c not in used:
                city = c
                break

        if city == -1:
            return len(used) == N  # all cities paired

        # Try pairing city with each available partner
        for partner in range(1, N + 1):
            if partner <= N and partner not in used and partner != city:
                match[city] = partner
                match[partner] = city
                used.add(city)
                used.add(partner)

                if is_stable():
                    # Check if all cities are paired
                    all_matched = all(c in used for c in range(1, N + 1))
                    if all_matched:
                        return True

                # Backtrack
                match[city] = 0
                match[partner] = 0
                used.remove(city)
                used.remove(partner)

        return False

    used = set()
    if backtrack(1, used):
        result = [str(match[i]) for i in range(1, N + 1)]
        return '\n'.join(result) + '\n'

