        if start_node in active_nodes:
            return 0
        inactive = set(range(N)) - active_nodes
        # BFS within inactive nodes
        visited = set()
        queue = deque([start_node])
        visited.add(start_node)
        while queue:
            curr = queue.popleft()
            for neighbor in adj[curr]:
