from itertools import combinations

def solution(input_data):
    lines = input_data.strip().split('\n')
    n = int(lines[0])

    contacts = []
    for i in range(1, n + 1):
        contacts.append(lines[i])

    predictions = list(map(int, lines[n + 1].split()))

    def count_messages(employees):
        actual = [0] * n
        for emp in employees:
            emp_idx = emp - 1
            for j in range(n):
                if contacts[emp_idx][j] == '1':
                    actual[j] += 1
        return actual

    # Check all possible subsets by size from 0 to n
    for size in range(n + 1):
        for combo in combinations(range(1, n + 1), size):
            actual = count_messages(combo)
            if all(actual[j] != predictions[j] for j in range(n)):
                result_lines = [str(size)]
                if size > 0:
                    result_lines.append(' '.join(map(str, combo)))
                return '\n'.join(result_lines)

    return "-1"


if __name__ == '__main__':
    import sys
    print(solution(sys.stdin.read()))
