Looking at this problem, I need to:

1. Understand that each pipe type has 2 endpoints at specific positions (top, bottom, left, right)
2. Validate that every pipe endpoint either connects to a border or connects to another pipe's matching endpoint
3. Count the number of ways to fill empty cells (marked '.') to make the system non-leaking

Let me trace through the logic:

- Pipe 1: top + left endpoints
- Pipe 2: top + right endpoints  
- Pipe 3: bottom + left endpoints
- Pipe 4: bottom + right endpoints

For a non-leaking system, each endpoint must point either to a border (valid) or to a matching endpoint from a neighbor cell (valid), or to an occupied cell that doesn't match (invalid/leak).

This can be solved with backtracking with memoization since we process cell by cell.

```python
import sys
from functools import lru_cache

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    grid = [lines[i+1] for i in range(n)]

    MOD = 1000003

    # Each pipe type and its endpoints
    ends = {
        '1': {'top': True, 'left': True},
        '2': {'top': True, 'right': True},
        '3': {'bottom': True, 'left': True},
        '4': {'bottom': True, 'right': True}
    }

    def ends_check(r, c, pipe_type):
        """Check if placement of pipe_type at (r, c) is valid"""
        p = ends[pipe_type]

        if p['top'] and r > 0:
            # Must have bottom from neighbor above
            if grid[r-1][c] != '.' and not ends[grid[r-1][c]].get('bottom', False):
                return False
        elif p['top'] and r == 0:
            # Top border - valid

        if p['bottom'] and r < n - 1:
            # Must have top from neighbor below
            if grid[r+1][c] != '.' and not ends[grid[r+1][c]].get('top', False):
                return False
        elif p['bottom'] and r == n - 1:
            # Bottom border - valid

        if p['left'] and c > 0:
            # Must have right from neighbor left
            if grid[r][c-1] != '.' and not ends[grid[r][c-1]].get('right', False):
                return False
        elif p['left'] and c == 0:
            # Left border - valid

        if p['right'] and c < m - 1:
            # Must have left from neighbor right
            if grid[r][c+1] != '.' and not ends[grid[r][c+1]].get('left', False):
                return False
        elif p['right'] and c == m - 1:
            # Right border - valid

        return True

    def check_initial_valid():
        """If any pre-filled cell is invalid, return 0"""
        for r in range(n):
            for c in range(m):
                if grid[r][c] != '.':
                    if not ends_check(r, c, grid[r][c]):
                        return False
        return True

    def count_ways(r, c, cache):
        """Recursively count valid fillings with memoization"""
        if r == n:
            return 1
        if (r, c) in cache:
            return cache[(r, c)]

        if grid[r][c] == '.':
            ans = 0
            for p in ['1', '2', '3', '4']:
                temp = [ch for ch in grid[r]]
                temp[c] = p
                grid[r] = temp
                if ends_check(r, c, p):
                    ans = (ans + count_ways(r, c + 1, cache)) % MOD
                grid[r] = ['.'] * m
            cache[(r, c)] = ans
            return ans
        else:
            count = count_ways(r, c + 1, cache)
            cache[(r, c)] = count
            return count

    if not check_initial_valid():
        return '0'

    cache = {}
    result = count_ways(0, 0, cache)
    return str(result)

